    private TaczGunDefinitions() {}

    public record Gun(String id, String ammoId, int magazineSize, int[] extendedMagSizes, int reloadTicks, int rpm, float bulletSpeed, float inaccuracy, float damage, int bulletCount, int lifeTicks, float gravity, float friction, int pierce, float headshotMultiplier, float knockback, Set<TaczAttachmentType> attachmentTypes, Set<String> attachmentIds) {
        public int extendedMagazineSize(int level) { return level > 0 && level <= this.extendedMagSizes.length ? this.extendedMagSizes[level - 1] : this.magazineSize; }
        @Override public String toString() { return this.id; }
    }
    public record Ammo(String id, int stackSize) {}
    public record Attachment(String id, TaczAttachmentType type, int level) {}
